-- 2026-11-18: yeni sorular 3 alintilarini duz cift tirnaga cevirir
--
-- NICIN: 2026-11-14_yeni_sorular_3.sql canlida uygulandi; yerel bankadaki
-- (assets/data/yeni3_2026_11_14_questions.json) alinti tirnaklari ev bicimine
-- (duz cift tirnak, bkz. question_quotation_style_test / question_typography_test)
-- cevrildi (tek tirnak, guillemet ve egri tirnak -> duz cift tirnak; kesme
-- isaretleri korundu). Sunucu ve yerel ayni soruda ayni metni gostersin diye
-- ayni degisiklik sunucuya uygulanir. Ek olarak Turkce harfli ozel adlar
-- (Turk filmi/roman adi: Kurk Mantolu Madonna, Okul Tirasi, Gurbet Kuslari,
-- Karpuz Kabugundan Gemiler Yapmak, Hababam Sinifi, Babam ve Oglum) Kurmanci
-- tasiyici cumlede cilpak durmasin diye alintiya alindi (yalniz tirnak eklenir).
--
-- KAPSAM: 163 soru, 357 (id, sutun) cifti (prompt 153, explanation 92, explanation_ku 92, explanation_tr 20); sunucuda olmayan
-- alanlar (promptTr, Turkce JSON explanation) dahil degildir. Elenen sorular
-- (2026-11-18_yeni_sorular_3_eleme.sql) bu listede yoktur.
--
-- ON KOSUL: bir satir yalniz sutun degeri BEKLENEN ESKI metne esitse guncellenir;
-- baska bir degerse dokunulmaz ve sayilir. Zaten yeni degerdeyse "zaten" sayilir.
-- IDEMPOTENT: ikinci calistirmada her sey "zaten" cikar, hicbir satir degismez.
-- Sonuc NOTICE olarak yazilir: uygulanan / zaten / uyusmayan / bulunamayan.
-- Geri alma: supabase/geri_al/2026-11-18_yeni_sorular_3_tirnak_geri.sql

begin;

create temp table _tirnak (local_id text, id uuid, col text, eski text, yeni text) on commit drop;


do $$
declare
  r record;
  n int;
  v_uygulanan int := 0;
  v_zaten int := 0;
  v_uyusmayan int := 0;
  v_yok int := 0;
  v_simdiki text;
begin
  for r in select * from _tirnak loop
    execute format('select %I from questions where id = $1', r.col)
      into v_simdiki using r.id;
    get diagnostics n = row_count;
    if n = 0 then
      v_yok := v_yok + 1;
    elsif v_simdiki is not distinct from r.yeni then
      v_zaten := v_zaten + 1;
    elsif v_simdiki is not distinct from r.eski then
      execute format('update questions set %I = $1 where id = $2 and %I = $3', r.col, r.col)
        using r.yeni, r.id, r.eski;
      v_uygulanan := v_uygulanan + 1;
    else
      v_uyusmayan := v_uyusmayan + 1;
      raise notice 'uyusmayan, dokunulmadi: % %', r.local_id, r.col;
    end if;
  end loop;
  raise notice 'tirnak gocu: uygulanan=% zaten=% uyusmayan=% bulunamayan=% (toplam %)',
    v_uygulanan, v_zaten, v_uyusmayan, v_yok, (select count(*) from _tirnak);
end $$;

commit;
